  15 int store_open(const char* path, Store* out)
  16 {
  17   if (!path || !out) return -EINVAL;
  18   if (path[0] == '\0') return -EINVAL;
  19 #ifdef _WIN32
  20   if (strchr(path, '/')) return -EINVAL; /* Windows callers must use backslashes */
  21 #endif
  22   FILE* f = fopen(path, "rb");
  23   if (!f) return -ENOENT;
  24 
  25   uint8_t hdr[7];
  26   if (fread(hdr, 1, sizeof hdr, f) != sizeof hdr) { fclose(f); return -EIO; }
  27   if (hdr[0] != 'S' || hdr[1] != 'T') { fclose(f); return -EBADMSG; }
  28   if (hdr[2] != 1) { fclose(f); return -EBADMSG; }
  29   size_t len = hdr[3] | (hdr[4] << 8) | (hdr[5] << 16) | ((size_t)hdr[6] << 24);
  30   if (len > STORE_MAX_LEN) { fclose(f); return -EFBIG; }
  31 
  32   uint8_t* buf = malloc(len ? len : 1);
  33   if (!buf) { fclose(f); return -ENOMEM; }
  34   if (fread(buf, 1, len, f) != len) { free(buf); fclose(f); return -EIO; }
  35 
  36   uint8_t sum;
  37   if (fread(&sum, 1, 1, f) != 1 || sum != xor_all(buf, len)) {
  38     free(buf); fclose(f); return -EBADMSG;
  39   }
  40   fclose(f);
  41   out->data = buf;
  42   out->len = len;
  43   return 0;
  44 }
  45 
  46 void store_close(Store* s)
  47 {
  48   if (s && s->data) { free(s->data); s->data = NULL; s->len = 0; }
  49 }
