#include "store.h"

#include <assert.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>

/* Four little-endian bytes of a 32-bit length, for use inside an initializer. */
#define LEN_LE(v) \
  (unsigned char)(v), (unsigned char)((v) >> 8), (unsigned char)((v) >> 16), (unsigned char)((v) >> 24)

static const char* write_file(const char* name, const unsigned char* bytes, size_t n)
{
  FILE* f = fopen(name, "wb");
  assert(f);
  fwrite(bytes, 1, n, f);
  fclose(f);
  return name;
}

/* store_open must reject the file with `code` and leave `out` untouched. */
static void expect_reject(const char* name, const unsigned char* bytes, size_t n, int code)
{
  Store s = {0};
  assert(store_open(write_file(name, bytes, n), &s) == code);
  assert(s.data == NULL && s.len == 0);
}

static void test_happy_path(void)
{
  const unsigned char good[] = {'S', 'T', 1, 3, 0, 0, 0, 'a', 'b', 'c', 'a' ^ 'b' ^ 'c'};
  Store s = {0};
  assert(store_open(write_file("good.bin", good, sizeof good), &s) == 0);
  assert(s.len == 3 && memcmp(s.data, "abc", 3) == 0);
  store_close(&s);
  assert(s.data == NULL);
}

static void test_empty_payload(void)
{
  const unsigned char empty[] = {'S', 'T', 1, 0, 0, 0, 0, /* checksum of nothing */ 0};
  Store s = {0};
  assert(store_open(write_file("empty.bin", empty, sizeof empty), &s) == 0);
  assert(s.len == 0 && s.data != NULL);
  store_close(&s);
}

static void test_bad_arguments(void)
{
  Store s = {0};
  assert(store_open(NULL, &s) == -EINVAL);
  assert(store_open("good.bin", NULL) == -EINVAL);
  assert(store_open("", &s) == -EINVAL);
  assert(store_open("does-not-exist.bin", &s) == -ENOENT);
  assert(s.data == NULL && s.len == 0);
}

static void test_bad_header(void)
{
  const unsigned char short_header[] = {'S', 'T', 1, 3, 0, 0};
  const unsigned char bad_magic_0[] = {'X', 'T', 1, 3, 0, 0, 0, 'a', 'b', 'c', 'a' ^ 'b' ^ 'c'};
  const unsigned char bad_magic_1[] = {'S', 'X', 1, 3, 0, 0, 0, 'a', 'b', 'c', 'a' ^ 'b' ^ 'c'};
  const unsigned char bad_version[] = {'S', 'T', 2, 3, 0, 0, 0, 'a', 'b', 'c', 'a' ^ 'b' ^ 'c'};
  const unsigned char too_big[] = {'S', 'T', 1, LEN_LE(STORE_MAX_LEN + 1)};
  expect_reject("short-header.bin", short_header, sizeof short_header, -EIO);
  expect_reject("bad-magic-0.bin", bad_magic_0, sizeof bad_magic_0, -EBADMSG);
  expect_reject("bad-magic-1.bin", bad_magic_1, sizeof bad_magic_1, -EBADMSG);
  expect_reject("bad-version.bin", bad_version, sizeof bad_version, -EBADMSG);
  expect_reject("too-big.bin", too_big, sizeof too_big, -EFBIG);
}

static void test_bad_body(void)
{
  const unsigned char short_payload[] = {'S', 'T', 1, 3, 0, 0, 0, 'a', 'b'};
  const unsigned char no_checksum[] = {'S', 'T', 1, 3, 0, 0, 0, 'a', 'b', 'c'};
  const unsigned char bad_checksum[] = {'S', 'T', 1, 3, 0, 0, 0, 'a', 'b', 'c', 0xFF};
  expect_reject("short-payload.bin", short_payload, sizeof short_payload, -EIO);
  expect_reject("no-checksum.bin", no_checksum, sizeof no_checksum, -EBADMSG);
  expect_reject("bad-checksum.bin", bad_checksum, sizeof bad_checksum, -EBADMSG);
}

int main(void)
{
  test_happy_path();
  test_empty_payload();
  test_bad_arguments();
  test_bad_header();
  test_bad_body();
  return 0;
}
EOF
